/* Swap every field of a 0x1DFD0-byte save block between GameCube and PC byte order (its own inverse) */
void pc_save_swap_fields(uint8_t* block) {
    for (int i = 0; i < 21198; i++) {
        uint8_t* p = block + s_offsets[i];
        uint8_t t;
        if (s_widths[i] == 2) {
            t = p[0]; p[0] = p[1]; p[1] = t;
        } else {
            t = p[0]; p[0] = p[3]; p[3] = t;
            t = p[1]; p[1] = p[2]; p[2] = t;
        }
    }
}
